<script setup lang="ts">
import { useDemoStore } from '~/stores/demo'
import { useSessionStore } from '~/stores/session'
definePageMeta({layout:'workspace'});import{selectPublicAnalytics}from'~/demo/selectors.mjs';const demo=useDemoStore(),session=useSessionStore();const filters=reactive({query:'',organizationId:'',networkId:'',startDate:'',endDate:''});const result=computed(()=>selectPublicAnalytics(demo.data,session.session||{},filters));const averageVideoViews=computed(()=>result.value.videos.length?Math.round(result.value.periodVideoViews/result.value.videos.length):0);const topVideos=computed(()=>result.value.videos.slice(0,8));</script>
<template><div class="page-content"><div class="page-title-row"><div><span class="page-label">PUBLIC YOUTUBE ANALYTICS</span><h1>Channel performance.</h1><p>Rounded channel counters are from the P2P Labs snapshot; video rows are demo fixtures, separate from campaign data.</p></div><span class="tag tag-muted">DEMO DATA</span></div><div class="metric-grid"><div class="metric-panel"><span class="metric-label">Channels in scope</span><strong class="metric-value">{{result.channels.length}}</strong><span class="metric-note">Based on current role</span></div><div class="metric-panel"><span class="metric-label">Lifetime channel views</span><strong class="metric-value">{{(result.lifetimeViews/1000000).toFixed(1)}}M</strong><span class="metric-note">Cumulative counters</span></div><div class="metric-panel"><span class="metric-label">Sample video rows</span><strong class="metric-value">{{result.videos.length}}</strong><span class="metric-note">Publication-date filter</span></div><div class="metric-panel"><span class="metric-label">Avg views per listed video</span><strong class="metric-value">{{averageVideoViews.toLocaleString()}}</strong><span class="metric-note">Cumulative video views</span></div></div><div class="filter-row"><input v-model="filters.query" class="filter-field search-field" placeholder="Search channels or videos"><select v-model="filters.organizationId" class="filter-field"><option value="">All organizations</option><option v-for="o in demo.data.organizations" :key="o.id" :value="o.id">{{o.name}}</option></select><select v-model="filters.networkId" class="filter-field"><option value="">All networks</option><option v-for="n in demo.data.networks" :key="n.id" :value="n.id">{{n.name}}</option></select><label class="form-field">Published after<input v-model="filters.startDate" type="date" class="filter-field"></label><label class="form-field">Published before<input v-model="filters.endDate" type="date" class="filter-field"></label></div><div class="dashboard-columns"><section class="panel"><div class="panel-head"><div><h2>Channel overview</h2><p>Lifetime statistics from public profile data</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Channel</th><th>Subscribers</th><th>Lifetime views</th><th>Public videos</th></tr></thead><tbody><tr v-for="c in result.channels" :key="c.id"><td><strong>{{c.title}}</strong><div class="secondary-text">{{c.handle || "Public handle not included in snapshot"}}</div></td><td>{{c.subscriberCount?.toLocaleString()||'Hidden'}}</td><td>{{c.totalViews.toLocaleString()}}</td><td>{{c.videoCount ?? "Not in source snapshot"}}</td></tr></tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Top videos</h2><p>Sorted by cumulative views</p></div></div><div class="bar-list"><div v-for="video in topVideos" :key="video.id" class="bar-item"><strong :title="video.title">{{video.title}}</strong><span class="metric-bar-track"><span class="metric-bar-fill" :style="{width:`${Math.max(5,video.views/(topVideos[0]?.views||1)*100)}%`,display:'block'}"></span></span><span>{{(video.views/1000).toFixed(0)}}K</span></div><p v-if="!topVideos.length" class="empty-state">No videos match these filters.</p></div></section></div><p class="form-hint">Channel views and subscriber counts are rounded organization snapshots. Video views, likes and comments are demo fixtures, not live YouTube Analytics.</p></div></template>
